import re
import random
import string

with open("/app/regex.txt") as f:
    pattern = f.read().strip()

MAXDAY = {1:31,2:29,3:31,4:30,5:31,6:30,7:31,8:31,9:30,10:31,11:30,12:31}

def isalnum(c):
    return ("0" <= c <= "9") or ("a" <= c <= "z") or ("A" <= c <= "Z")

def valid_ip(s):
    parts = s.split(".")
    if len(parts) != 4:
        return False
    for p in parts:
        if not p or not p.isdigit():
            return False
        if len(p) > 1 and p[0] == "0":
            return False
        if int(p) > 255:
            return False
    return True

def valid_date(s):
    if len(s) != 10 or s[4] != "-" or s[7] != "-":
        return False
    y, m, d = s[:4], s[5:7], s[8:10]
    if not (y.isdigit() and m.isdigit() and d.isdigit()):
        return False
    mm, dd = int(m), int(d)
    if not (1 <= mm <= 12):
        return False
    if not (1 <= dd <= MAXDAY[mm]):
        return False
    return True

def ref_line(line):
    has_ip = False
    for m in re.finditer(r"\d{1,3}(?:\.\d{1,3}){3}", line):
        i, j = m.start(), m.end()
        if (i == 0 or not isalnum(line[i-1])) and (j == len(line) or not isalnum(line[j])):
            if valid_ip(m.group(0)):
                has_ip = True
                break
    if not has_ip:
        return None
    best_i, best_s = -1, None
    for m in re.finditer(r"\d{4}-\d{2}-\d{2}", line):
        i, j = m.start(), m.end()
        if (i == 0 or not isalnum(line[i-1])) and (j == len(line) or not isalnum(line[j])):
            if valid_date(m.group(0)):
                if i > best_i:
                    best_i, best_s = i, m.group(0)
    return best_s

def rand_octet():
    return str(random.randint(0, 300))

def rand_date():
    mm = random.randint(0, 13)
    dd = random.randint(0, 35) if mm in (1,3,5,7,8,10,12) else random.randint(0, 32)
    return f"{random.randint(0,9999):04d}-{mm:02d}-{dd:02d}"

def rand_ip():
    if random.random() < 0.3:
        # inject leading zero
        parts = [rand_octet() for _ in range(4)]
        k = random.randrange(4)
        v = int(parts[k])
        parts[k] = str(v).zfill(2 if v < 10 else 3)
        return ".".join(parts)
    if random.random() < 0.7:
        return ".".join(str(random.randint(0, 255)) for _ in range(4))
    return ".".join(str(random.randint(0, 300)) for _ in range(4))

def rand_junk():
    n = random.randint(1, 8)
    return "".join(random.choice(string.ascii_letters + string.digits) for _ in range(n))

SEPS = [" ", " ", " ", ".", "-", ",", "_", ":", ";", "  "]

def rand_token():
    r = random.random()
    if r < 0.30:
        return rand_date()
    if r < 0.60:
        return rand_ip()
    if r < 0.85:
        return rand_junk()
    # version-like / id-like trap
    return f"{random.randint(1000,9999)}-{random.randint(1,12):02d}-{random.randint(100,999)}"

def gen_line():
    n = random.randint(1, 8)
    toks = [rand_token() for _ in range(n)]
    line = toks[0]
    for t in toks[1:]:
        if random.random() < 0.85:
            line += random.choice(SEPS)
        line += t
    return line

random.seed(12345)
lines = [gen_line() for _ in range(20000)]
log = "\n".join(lines)

got = re.findall(pattern, log, re.MULTILINE)
exp = [r for r in (ref_line(l) for l in lines) if r is not None]

print(f"lines={len(lines)} got={len(got)} exp={len(exp)}")
if got != exp:
    # find first divergence
    gi = ei = 0
    line_i = 0
    # walk lines, consume got/exp in order
    # simpler: recompute per-line and compare sequence positions
    pos_g = 0
    for i, l in enumerate(lines):
        r = ref_line(l)
        if r is None:
            continue
        if pos_g >= len(got) or got[pos_g] != r:
            print(f"first divergence at line {i}: {l!r}")
            print(f"  ref={r}")
            print(f"  got slice={got[pos_g:pos_g+3]}")
            # also show what the regex matched on this line directly
            print(f"  direct: {re.findall(pattern, l, re.MULTILINE)}")
            break
        pos_g += 1
    else:
        if pos_g != len(got):
            print(f"extra matches in got: {got[pos_g:pos_g+5]}")
    raise SystemExit(1)
print("FUZZ OK - regex agrees with brute-force reference on 20000 random lines")

